#include <cstdint>
#include <cstring>
#include <vector>
#include <array>
#include <algorithm>
#include <functional>
#include <openssl/evp.h>
#include <openssl/rand.h>

namespace crypto_stream {

struct StreamConfig {
    static constexpr int32_t COUNTER_START = 2147483520;  // INT32_MAX - 127
    static constexpr size_t BLOCK_SIZE = 64;
    static constexpr size_t KEY_SIZE = 32;
    static constexpr size_t NONCE_SIZE = 12;
    static constexpr size_t TAG_SIZE = 16;
    static constexpr size_t MAX_BLOCKS_PER_MESSAGE = 256;
};

class NonceGenerator {
public:
    explicit NonceGenerator(const uint8_t* base_nonce) {
        std::memcpy(base_nonce_.data(), base_nonce, StreamConfig::NONCE_SIZE);
        counter_ = StreamConfig::COUNTER_START;
    }

    // Generate next nonce by incrementing counter and XORing with base
    bool next_nonce(uint8_t* out_nonce) {
        counter_ += 1;  // signed increment
        // Encode counter into last 4 bytes of nonce
        uint32_t counter_bits = static_cast<uint32_t>(counter_);
        std::memcpy(out_nonce, base_nonce_.data(), StreamConfig::NONCE_SIZE);
        // XOR counter into nonce bytes 8-11
        out_nonce[8] ^= (counter_bits >> 24) & 0xFF;
        out_nonce[9] ^= (counter_bits >> 16) & 0xFF;
        out_nonce[10] ^= (counter_bits >> 8) & 0xFF;
        out_nonce[11] ^= counter_bits & 0xFF;
        return true;
    }

    int32_t get_counter() const { return counter_; }

private:
    std::array<uint8_t, StreamConfig::NONCE_SIZE> base_nonce_;
    int32_t counter_;
};

class SecureStream {
public:
    SecureStream(const uint8_t* key, const uint8_t* base_nonce)
        : nonce_gen_(base_nonce), messages_processed_(0) {
        std::memcpy(key_.data(), key, StreamConfig::KEY_SIZE);
    }

    // Encrypt a message with authenticated encryption
    // Returns ciphertext with prepended nonce and appended tag
    std::vector<uint8_t> encrypt_message(const uint8_t* plaintext, size_t pt_len) {
        if (pt_len == 0 || pt_len > StreamConfig::MAX_BLOCKS_PER_MESSAGE * StreamConfig::BLOCK_SIZE) {
            return {};
        }

        std::vector<uint8_t> output;
        output.resize(StreamConfig::NONCE_SIZE + pt_len + StreamConfig::TAG_SIZE);

        uint8_t nonce[StreamConfig::NONCE_SIZE];
        nonce_gen_.next_nonce(nonce);

        // Prepend nonce
        std::memcpy(output.data(), nonce, StreamConfig::NONCE_SIZE);

        // Encrypt with AES-256-GCM
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return {};

        int len = 0;
        int ct_len = 0;

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        if (EVP_EncryptInit_ex(ctx, nullptr, nullptr, key_.data(), nonce) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        if (EVP_EncryptUpdate(ctx, output.data() + StreamConfig::NONCE_SIZE, &len,
                             plaintext, static_cast<int>(pt_len)) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }
        ct_len = len;

        if (EVP_EncryptFinal_ex(ctx, output.data() + StreamConfig::NONCE_SIZE + ct_len, &len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }
        ct_len += len;

        // Get tag
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, StreamConfig::TAG_SIZE,
                               output.data() + StreamConfig::NONCE_SIZE + ct_len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        EVP_CIPHER_CTX_free(ctx);
        messages_processed_++;
        return output;
    }

    // Decrypt and verify a message
    std::vector<uint8_t> decrypt_message(const uint8_t* ciphertext, size_t ct_total_len) {
        if (ct_total_len <= StreamConfig::NONCE_SIZE + StreamConfig::TAG_SIZE) {
            return {};
        }

        size_t ct_len = ct_total_len - StreamConfig::NONCE_SIZE - StreamConfig::TAG_SIZE;
        if (ct_len > StreamConfig::MAX_BLOCKS_PER_MESSAGE * StreamConfig::BLOCK_SIZE) {
            return {};
        }

        const uint8_t* nonce = ciphertext;
        const uint8_t* ct_data = ciphertext + StreamConfig::NONCE_SIZE;
        const uint8_t* tag = ciphertext + StreamConfig::NONCE_SIZE + ct_len;

        std::vector<uint8_t> plaintext(ct_len);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return {};

        int len = 0;
        int pt_len = 0;

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        if (EVP_DecryptInit_ex(ctx, nullptr, nullptr, key_.data(), nonce) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        if (EVP_DecryptUpdate(ctx, plaintext.data(), &len,
                             ct_data, static_cast<int>(ct_len)) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }
        pt_len = len;

        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, StreamConfig::TAG_SIZE,
                               const_cast<uint8_t*>(tag)) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        if (EVP_DecryptFinal_ex(ctx, plaintext.data() + pt_len, &len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        EVP_CIPHER_CTX_free(ctx);
        return plaintext;
    }

    size_t get_messages_processed() const { return messages_processed_; }

private:
    std::array<uint8_t, StreamConfig::KEY_SIZE> key_;
    NonceGenerator nonce_gen_;
    size_t messages_processed_;
};

// Session manager that creates streams for bidirectional communication
class SessionManager {
public:
    struct Session {
        SecureStream* send_stream;
        SecureStream* recv_stream;
        uint64_t session_id;
        bool active;
    };

    SessionManager() : next_session_id_(1) {}
    ~SessionManager() {
        for (auto& s : sessions_) {
            delete s.send_stream;
            delete s.recv_stream;
        }
    }

    // Create a new session with random keys
    int create_session() {
        uint8_t send_key[StreamConfig::KEY_SIZE];
        uint8_t recv_key[StreamConfig::KEY_SIZE];
        uint8_t send_nonce[StreamConfig::NONCE_SIZE];
        uint8_t recv_nonce[StreamConfig::NONCE_SIZE];

        if (RAND_bytes(send_key, sizeof(send_key)) != 1) return -1;
        if (RAND_bytes(recv_key, sizeof(recv_key)) != 1) return -1;
        if (RAND_bytes(send_nonce, sizeof(send_nonce)) != 1) return -1;
        if (RAND_bytes(recv_nonce, sizeof(recv_nonce)) != 1) return -1;

        Session s;
        s.send_stream = new SecureStream(send_key, send_nonce);
        s.recv_stream = new SecureStream(recv_key, recv_nonce);
        s.session_id = next_session_id_++;
        s.active = true;

        sessions_.push_back(s);
        return static_cast<int>(sessions_.size() - 1);
    }

    // Send a message on a session
    std::vector<uint8_t> send(int session_idx, const uint8_t* data, size_t len) {
        if (session_idx < 0 || static_cast<size_t>(session_idx) >= sessions_.size()) {
            return {};
        }
        if (!sessions_[session_idx].active) return {};
        return sessions_[session_idx].send_stream->encrypt_message(data, len);
    }

    // Receive (decrypt) a message on a session
    std::vector<uint8_t> receive(int session_idx, const uint8_t* data, size_t len) {
        if (session_idx < 0 || static_cast<size_t>(session_idx) >= sessions_.size()) {
            return {};
        }
        if (!sessions_[session_idx].active) return {};
        return sessions_[session_idx].recv_stream->decrypt_message(data, len);
    }

private:
    std::vector<Session> sessions_;
    uint64_t next_session_id_;
};

} // namespace crypto_stream
